(window.LADDER_CARDS=window.LADDER_CARDS||{})["16·then"]=[{"q":"Q(T) = Q(0) + ∫₀ᵀ Q′(t) dt. Which technique?","a":"net-change","w":["area-slope","antiderivative-exists","impulse"],"why":"Area-is-a-change with G = Q."},{"q":"Cars enter at 40 + 6t a minute and leave at 30 + 9t. What is Q′?","a":"10 − 3t","w":["70 + 15t","3t − 10","10 + 3t"],"why":"Q′ = in − out."},{"q":"Inflow peaks at noon. Is the lake fullest then?","a":"no: fullest where in − out goes from + to −","w":["yes","yes, if the outflow is steady","no: fullest at the start"],"why":"V rises as long as in > out."},{"q":"∫₀²⁴ V′ dt = V(24)?","a":"no: it is V(24) − V(0)","w":["yes","yes, if V(0) is the start","no: it is V′(24)"],"why":"The change, not the amount."},{"q":"A rate in m³ a second, the time in hours. The integral?","a":"off by 3600 until the units agree","w":["right as it stands","off by 60","off by 24"],"why":"Seconds against hours."},{"q":"Left sum ≤ total ≤ right sum, always?","a":"no: only if the rate never falls","w":["yes","yes, for any rain","no: the reverse, always"],"why":"A rate that rises and falls breaks it."},{"q":"Gauge readings each hour: 0, 0, 0, 0. Did no rain fall?","a":"not shown: it could spike between","w":["yes","yes, by net-change","no: some must have"],"why":"With readings alone, no technique pins the total."},{"q":"A valve shuts at once, so Q′ jumps. What still gives the total?","a":"change-for-any-integrable","w":["area-slope","antiderivative-exists","nothing"],"why":"It asks only an integrable rate and a continuous Q."}];
